نَا عَذَابَ ٱلنَّارِ', 'dua-for-balanced-life-surah-al-baqara-2-201', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://oveuimwssgsadagddtef.supabase.co/storage/v1/object/public/media/dua-og/dua-for-balanced-life-surah-al-baqara-2-201.webp?v=1785779719332', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL);

