E, NULL, NULL, NULL, NULL),
('dbe2c211-ff87-4b96-b95c-3266a774991b', 'dua', 'বংশধরদের জন্য বরকতের দোয়া', 'دعاء من سورة سُورَةُ إِبۡرَاهِيمَ (14:37)', 'Dua of Ibrahim for His Family in the Barren Valley', 'परिवार और नेक औलाद की भलाई की दुआ', 'اہلِ خانہ اور اولاد کی بھلائی کی دعا', 'হে আমাদের পালনকর্তা, আমি নিজের এক সন্তানকে তোমার পবিত্র গৃহের সন্নিকটে চাষাবাদহীন উপত্যকায় আবাদ করেছি; হে আমাদের পালনকর্তা, যাতে তারা নামায কায়েম রাখে। অতঃপর আপনি কিছু লোকের অন্তরকে তাদের প্রতি আকৃষ্ট করুন এবং তাদেরকে ফলাদি দ্বারা রুযী দান করুন, সম্ভবতঃ তারা কৃতজ্ঞতা প্রকাশ করবে', 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةًۭ مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', '"O our Sustainer! Behold, I have settled some of my offspring in a valley in which there is no arable land, close to Thy sanctified Temple, so that, O our Sustainer, they might devote themselves to prayer: cause Thou, therefore, people''s hearts to incline towards them and grant them fruitful sustenance, so that they might have cause to be grateful.', NULL, NULL, 'রাব্বানা ইন্নী আসকান্তু মিন যুররিয়্যাতী বিওয়াদিন গাইরি যী যার''ইন ইনদা বাইতিকাল মুহাররামি রাব্বানা লিয়ুকীমুস সালাওয়াতা ফাজ''আল আফইদাতাম মিনান নাসি তাহওয়ী ইলাইহিম ওয়ারযুকহুম মিনাস সামারাতি লা''আল্লাহুম ইয়াশকুরূন', 'Family', NULL, NULL, NULL, TRUE, 0, '{"faq": [{"a": "Its primary focus is family, asked from Allah with humility and trust.", "q": "What is the main meaning of this dua?"}, {"a": "Recite it after salah, family gathering and whenever this need is present in your life.", "q": "When is it best to recite this dua?"}, {"a": "Read it with understanding of meaning, a soft heart, and sincere intention.", "q": "How should this dua be read?"}], "seo": {"meta_title": "Dua for righteous family and offspring | Surah Ibrahim 14:37", "search_intent": ["family", "offspring", "righteous_home"], "canonical_slug": "dua-for-rizq-surah-ibrahim-14-37", "focus_keywords": ["dua for righteous family and offspring", "quranic dua for family", "surah ibrahim 14:37"], "difficulty_level": "long", "meta_description": "Dua for righteous family and offspring from Surah Ibrahim 14:37. Understand the meaning and recite with sincerity.", "semantic_keywords": ["family", "family", "quranic supplication", "dua meaning"]}, "hook": "\u09aa\u09b0\u09bf\u09ac\u09be\u09b0 \u0993 \u09b8\u09a8\u09cd\u09a4\u09be\u09a8\u09c7\u09b0 \u0995\u09b2\u09cd\u09af\u09be\u09a3\u09c7\u09b0 \u09a6\u09cb\u09af\u09bc\u09be \u2014 \u09a6\u09cb\u09df\u09be \u0995\u0996\u09a8\u0993 \u099b\u09cb\u099f \u09b9\u09df \u09a8\u09be\u0964 \u098f\u0987\u099f\u09c1\u0995\u09c1\u0987 \u09af\u09a5\u09c7\u09b7\u09cd\u099f \u09b9\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964 (24)", "social": {"short": "\u098f\u0995 \u09ae\u09bf\u09a8\u09bf\u099f\u09c7\u09b0 \u0986\u09ae\u09b2, \u09a6\u09c0\u09b0\u09cd\u0998 \u09aa\u09cd\u09b0\u09ad\u09be\u09ac \u2022 14:37", "facebook": "\u09aa\u09b0\u09bf\u09ac\u09be\u09b0 \u0993 \u09b8\u09a8\u09cd\u09a4\u09be\u09a8\u09c7\u09b0 \u0995\u09b2\u09cd\u09af\u09be\u09a3\u09c7\u09b0 \u09a6\u09cb\u09af\u09bc\u09be (Surah Ibrahim 14:37) \u2014 \u09b9\u09df\u09a4\u09cb \u0986\u09aa\u09a8\u09bf \u09b6\u0995\u09cd\u09a4; \u09a4\u09ac\u09c1 \u09a6\u09cb\u09df\u09be \u0986\u09aa\u09a8\u09be\u0995\u09c7 \u0986\u09b0\u0993 \u0995\u09cb\u09ae\u09b2 \u0995\u09b0\u09c7\u0964", "whatsapp": "\u09aa\u09b0\u09bf\u09ac\u09be\u09b0 \u0993 \u09b8\u09a8\u09cd\u09a4\u09be\u09a8\u09c7\u09b0 \u0995\u09b2\u09cd\u09af\u09be\u09a3\u09c7\u09b0 \u09a6\u09cb\u09af\u09bc\u09be (Surah Ibrahim 14:37). \u098f\u0995\u099f\u09c1 \u09a5\u09c7\u09ae\u09c7 \u09aa\u09dc\u09b2\u09c7 \u09ad\u09be\u09b2\u09cb \u09b2\u09be\u0997\u09c7\u0964"}, "source": "Quran", "virtue": "Provision is from Allah; dua aligns effort with trust in Him.", "emotion": ["hope", "trust", "peace"], "benefits": ["\u0986\u09b2\u09cd\u09b2\u09be\u09b9\u09b0 \u0995\u09be\u099b\u09c7 \u09ab\u09bf\u0